// Carts with this many lines or more get the bulk discount.
export const BULK_MIN_LINES = 2;

// Cart total in cents. `discount` is the customer's discount rate (0.1 = 10%).
// Carts with `bulkMinLines` or more lines (2 by default) get an extra 5% bulk
// discount, applied once, after the customer's discount.
export function total(items, discount = 0, { bulkMinLines = BULK_MIN_LINES } = {}) {
  const subtotal = items.reduce((sum, item) => sum + item.price * item.qty, 0);
  const bulk = items.length >= bulkMinLines ? 0.05 : 0;
  return Math.round(subtotal * (1 - discount) * (1 - bulk));
}

export function itemCount(items) {
  return items.reduce((n, item) => n + item.qty, 0);
}
EOF
cat > src/invoice.js <<'EOF'
import { total } from './cart.js';

// The printed wholesale price list gives 5% off from 10 lines. This is pinned here
// so that changes to the shop cart's bulk threshold do not alter invoices.
const WHOLESALE_BULK_MIN_LINES = 10;

// Invoices for wholesale orders (#7). Wholesale customers order from a printed
// price list: list price below 10 lines, 5% off from 10 lines, half a yen rounded up.
export function invoice(customer, items) {
  return { customer, due: total(items, 0, { bulkMinLines: WHOLESALE_BULK_MIN_LINES }) };
}
EOF
